const ROSTER_SLOTS=15;
const roleRank=p=>p.owner?0:p.coach?1:p.captain?1.5:p.lineup==='starter'?2:p.lineup==='bench'?3:4;
const roster=id=>[...players,...players2].filter(p=>p.teamId===id).sort((a,b)=>roleRank(a)-roleRank(b)||(Number(a.number)||999)-(Number(b.number)||999)||a.name.localeCompare(b.name));
const roleTags=p=>[p.owner&&'<b class="role owner">Franchise Owner</b>',p.coach&&'<b class="role coach">Head Coach</b>',p.lineup==='starter'&&'<b class="role starter">Starter</b>',p.lineup==='bench'&&'<b class="role bench">Bench</b>'].filter(Boolean).join('');
const nick=t=>t.name.split(' ').slice(-1)[0];
const plain=s=>String(s||'').replace(/\*\*/g,'');
function mentions(t){
  // Newest post or media story that names the team (full name, nickname, abbreviation tag) or one of its players.
  const names=[t.name,nick(t),...roster(t.id).map(p=>p.name)].filter(n=>n&&n.length>2).map(n=>n.toLowerCase());
  const hit=(text,ids)=>(ids||[]).includes(t.id)||names.some(n=>new RegExp(`\\b${n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`,'i').test(text));
  const items=[...posts.map(p=>({kind:'post',date:p.date||'',id:p.id,who:p.name,handle:p.handle,avatar:p.avatar,text:plain(p.text),ids:p.teamIds})),
    ...media.map(m=>({kind:'media',date:m.date||'',id:m.id,who:m.category,title:m.title,text:[m.title,m.summary,...(m.body||[])].join(' '),ids:m.teamIds}))];
  return items.filter(i=>hit(i.text,i.ids)).sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0];
}
const hxc=(v,d)=>/^#[0-9a-f]{3,8}$/i.test(v||'')?v:d;
// Roster panel (standings drop-down + Players "by team" view)
const pinitials=n=>esc(String(n||'?').split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase());
const robloxUser=p=>{const u=String(p.roblox||p.username||'').replace(/^@/,'').trim();return u&&u.toLowerCase()!==String(p.name||'').toLowerCase()?u:'';};
function rosterPanel(t,{search=false}={}){
  const r=roster(t.id);const open=Math.max(0,ROSTER_SLOTS-r.length);
  const badges=p=>[p.captain&&'<b class="rp-badge cap" title="Captain">C</b>',p.owner&&'<b class="rp-badge own">Owner</b>',p.coach&&'<b class="rp-badge coach">Coach</b>'].filter(Boolean).join('');
  const meta=p=>[p.number!=null&&p.number!==''?`<b>#${esc(p.number)}</b>`:'',p.position?`<span>${esc(String(p.position).split(/[\/, ]+/).filter(Boolean).join(' / '))}</span>`:'',Number.isFinite(p.overall)?`<span class="rp-ovr">${esc(p.overall)} <small>OVR</small></span>`:''].filter(Boolean).join('');
  const row=p=>{const u=robloxUser(p);return `<li class="rp-row${p.captain?' is-cap':''}${p.owner?' is-owner':''}"${search?` data-rp-search="${esc([p.name,u,t.name].join(' ').toLowerCase())}"`:''}><span class="rp-av">${p.headshot?`<img src="${esc(p.headshot)}" alt="" loading="lazy" width="40" height="40">`:`<i>${pinitials(p.name)}</i>`}</span><span class="rp-id"><span class="rp-name"><span class="rp-dn">${esc(p.name)}</span>${badges(p)}</span>${u?`<span class="rp-user">@${esc(u)}</span>`:''}</span><span class="rp-meta">${meta(p)}</span></li>`;};
  const body=r.length?`<ul class="rp-list">${r.map(row).join('')}</ul>${open?`<p class="rp-open"><span class="rp-dot" aria-hidden="true"></span>${open} roster spot${open===1?'':'s'} available</p>`:''}`
    :`<div class="rp-empty">${url(t.logo)?`<img src="${url(t.logo)}" alt="" width="56" height="56" loading="lazy">`:''}<strong>No players signed yet</strong><span>${ROSTER_SLOTS} roster spots available</span></div>`;
  return `<section class="rp" style="--team:${hxc(t.color,'#3a3f47')}"><header class="rp-head"><h4>TEAM ROSTER</h4><span class="rp-count">${r.length} / ${ROSTER_SLOTS}</span></header>${body}</section>`;
}
function teamDrawer(t){
  const m=mentions(t);
  const tc=hxc(t.color,'#3a3f47');
  const news=m?`<a class="drawer-news" href="/media/#${esc(m.id)}">${m.avatar?`<img src="${url(m.avatar)}" alt="" width="40" height="40">`:''}<span><b>${esc(m.who)}</b>${m.handle?` <small>@${esc(m.handle)}</small>`:''}<span class="dn-text">${esc(m.title?m.title+' ':'')}${esc(m.text.length>220?m.text.slice(0,217).trim()+'…':m.text).slice(0,260)}</span></span></a>`:'<p class="drawer-empty">No media about this team yet.</p>';
  return `<div class="team-drawer v2" id="drawer-${esc(t.id)}" style="--team:${tc}" hidden>${rosterPanel(t)}<section class="rp rp-media"><header class="rp-head"><h4>LATEST MEDIA</h4></header>${news}</section></div>`;
}
const teamRecord=t=>Number.isFinite(t.wins)||Number.isFinite(t.losses)?{w:t.wins||0,l:t.losses||0}:stat(t.id);
const recPct=s=>s.w+s.l?s.w/(s.w+s.l):0;
const rankTeams=list=>list.map(t=>({t,s:teamRecord(t)})).sort((a,b)=>(a.t.seed??Infinity)-(b.t.seed??Infinity)||recPct(b.s)-recPct(a.s)||b.s.w-a.s.w||(a.t.officialRank??Infinity)-(b.t.officialRank??Infinity)||a.t.name.localeCompare(b.t.name));
const teamLogoImg=t=>url(t.logo)?`<img src="${url(t.logo)}" alt="" width="64" height="64" loading="lazy">`:`<span class="sc-monogram">${esc(t.abbreviation||t.name.slice(0,3))}</span>`;
const seedCardHTML=({t,s},attrs='')=>`<article class="seed-card"${attrs} style="--team:${hxc(t.color,'#3a3f47')};--p:${hxc(t.primary,'#ffffff')};--s:${hxc(t.secondary,'#d1d5db')}${t.nameOutline?`;--no:${hxc(t.nameOutline,'#000')}`:''}${t.nameScale?`;--ns:${Number(t.nameScale)||1}`:''}${url(t.logo)?`;--logo:url('${url(t.logo)}')`:''}">${url(t.logo)?'<span class="sc-mark" aria-hidden="true"></span>':''}<span class="sc-logo">${teamLogoImg(t)}</span><span class="sc-name"><strong data-n="${esc(t.name)}">${esc(t.name)}</strong></span><span class="sc-numbers"><span class="sc-record">${s.w}-${s.l}</span><small class="sc-lbl">W&ndash;L</small></span></article>`;
function playersPage(){
  const tlogo=t=>t&&url(t.logo)?`<img src="${url(t.logo)}" alt="" width="44" height="44" loading="lazy">`:'<span class="pc-fa">FA</span>';
  const pcard=p=>{const t=team(p.teamId);const f=team(p.formerTeamId);const status=t?'signed':'free-agent';
    return `<article class="player-card ${status}${p.owner?' is-owner':''}" data-filter-item data-category="${status}" data-search-value="${esc([p.name,t?.name,f?.name,p.position,status==='free-agent'?'free agent':''].filter(Boolean).join(' '))}"${t?` style="--team:${esc(t.color||'#3a3f47')}"`:''}>${tlogo(t)}<div class="pc-main"><strong>${esc(p.name)}</strong>${roleTags(p)?`<span class="pc-roles">${roleTags(p)}</span>`:''}<span>${t?esc(t.name):`Free Agent${f?` · formerly ${esc(f.name)}`:''}`}</span></div><div class="pc-meta">${p.position?`<span>${esc(p.position)}</span>`:''}${p.number!=null&&p.number!==''?`<b>#${esc(p.number)}</b>`:''}</div></article>`;};
  const byName=(a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'});
  const fa=players.filter(p=>!team(p.teamId)).sort(byName);
  const grid=list=>`<div class="player-grid">${list.map(pcard).join('')}</div>`;
  const ranked=rankTeams(teams);
  const groups=ranked.map((x,i)=>{return `<section class="pteam ${i<(standingsFormat.playoffSpots||6)?'tier-playoffs':''}" data-pgroup><div class="seed-row pteam-head"><span class="seed-num" aria-label="Rank ${i+1}">${i+1}</span>${seedCardHTML(x)}</div>${rosterPanel(x.t,{search:true})}</section>`;}).join('');
  const views=`<div class="pview" data-pview="alpha">${grid([...players].sort(byName))}</div><div class="pview" data-pview="team" hidden>${groups}</div><div class="pview" data-pview="fa" hidden>${fa.length?grid(fa):'<p class="pteam-empty">No free agents right now.</p>'}</div>`;
  return `<section class="players-board" data-players><div class="filter-toolbar page-toolbar players-toolbar"><label class="pview-select"><span class="sr-only">Sort players</span><select data-pview-select><option value="alpha">Alphabetical (${players.length})</option><option value="team">By Ranked Team (High to Low)</option><option value="fa">Free Agents (${fa.length})</option></select></label>${search('Search players or teams')}</div>${views}<p class="pteam-empty" data-pnone hidden>No players match your search.</p>`+`${!players.length?`<div class="data-panel">${empty('ball','THE PLAYER INDEX IS COMING.','Signed players and free agents will appear here as teams build their rosters.',link('View the standings','/standings/','button outline'))}</div>`:''}</section>`;
}
function spotlightCards(){
  if(!spotlights?.length)return '';
  const hx=(v,d)=>/^#[0-9a-f]{3,8}$/i.test(v||'')?v:d;
  const statLabels=[['pts','PTS'],['ast','AST'],['reb','REB'],['min','MIN'],['to','TO']];
  const cards=spotlights.map((sp,i)=>{const t=team(sp.teamId)||{};const opp=team(sp.opponentId);
    const stats=sp.look==='dnp'?'':`<dl class="spot-stats">${statLabels.filter(([k])=>sp.stats?.[k]!=null).map(([k,l])=>`<div><dt>${l}</dt><dd>${esc(sp.stats[k])}</dd></div>`).join('')}</dl>`;
    const when=sp.date&&Number.isFinite(Date.parse(sp.date+'T12:00:00Z'))?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(sp.date+'T12:00:00Z')):'';
    const vs=opp?`<div class="spot-vs${sp.look==='dnp'?' dnp':''}">${sp.look==='dnp'?'<b class="spot-dnp-tag">DNP</b>':''}<span class="spot-vs-word">vs</span>${url(opp.logo)?`<img src="${url(opp.logo)}" alt="" width="48" height="48">`:''}<span class="spot-vs-team">${esc(opp.name)}</span>${when?`<time datetime="${esc(sp.date)}">${esc(when)}</time>`:''}</div>`:(when?`<div class="spot-vs"><time datetime="${esc(sp.date)}">${esc(when)}</time></div>`:'');
    const badge=sp.look==='stinker'?'<span class="spot-badge">STINKER</span>':sp.look==='dnp'?'<span class="spot-badge">MISSING</span>':'';
    const fx=sp.look==='fire'?'<span class="spot-flames" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><span class="spot-emoji" aria-hidden="true"><i>🔥</i><i>🔥</i><i>🔥</i></span>':sp.look==='stinker'?'<span class="spot-emoji stink" aria-hidden="true"><i>💨</i><i>💨</i><i>🤢</i></span>':'';
    const label=sp.look==='dnp'?`${sp.player} did not play versus ${opp?.name||'their opponent'}`:`${sp.player}: ${statLabels.filter(([k])=>sp.stats?.[k]!=null).map(([k,l])=>sp.stats[k]+' '+l).join(', ')}`;
    return `<figure class="spotlight look-${esc(sp.look)}" data-spotlight="${i}"${i?' hidden':''} aria-label="${esc(label)}" style="--team:${hx(t.color,'#6d28d9')};--p:${hx(t.primary,'#c084fc')};--opp:${hx(opp?.color,'#4a2a14')};--opp2:${hx(opp?.secondary,'#f2b632')}">
<div class="spot-stage">${sp.look==='dnp'&&opp&&url(opp.logo)?`<img class="spot-opp-mark" src="${url(opp.logo)}" alt="" aria-hidden="true">`:''}${fx}<img class="spot-player" src="${url(sp.image)}" alt="" width="291" height="700">${badge}</div>
<figcaption><span class="spot-kicker">LAST GAME</span><div class="spot-who">${url(t.logo)?`<img src="${url(t.logo)}" alt="${esc(t.name||'')}" width="64" height="64">`:''}<strong class="spot-name">${esc(sp.player)}</strong></div>${vs}${stats}</figcaption></figure>`;}).join('');
  return `<aside class="spotlight-rail" aria-label="Player spotlight">${cards}</aside>`;
}
function standingsPage(lg={teams,standings:'/standings/',admin:'/admin/'}){
  // Card-style standings for the single RNBA Super Conference: Playoffs / Play-In / Out Of Playoffs tiers.
  const {playoffSpots=6,playInSpots=4,teamsPerConference=14}=lg.format||standingsFormat;
  const pct=s=>s.w+s.l?s.w/(s.w+s.l):0;
  const rec=t=>Number.isFinite(t.wins)||Number.isFinite(t.losses)?{w:t.wins||0,l:t.losses||0}:stat(t.id);
  const order=list=>list.map(t=>({t,s:rec(t)})).sort((a,b)=>(a.t.seed??Infinity)-(b.t.seed??Infinity)||pct(b.s)-pct(a.s)||b.s.w-a.s.w||(a.t.officialRank??Infinity)-(b.t.officialRank??Infinity)||a.t.name.localeCompare(b.t.name));
  const logo=t=>url(t.logo)?`<img src="${url(t.logo)}" alt="" width="64" height="64" loading="lazy">`:`<span class="sc-monogram">${esc(t.abbreviation||t.name.slice(0,3))}</span>`;
  const hx=(v,d)=>/^#[0-9a-f]{3,8}$/i.test(v||'')?v:d;
  const card=({t,s})=>`<article class="seed-card" tabindex="0" role="button" aria-expanded="false" aria-controls="drawer-${esc(t.id)}" aria-label="${esc(t.name)}: show roster and latest media" style="--team:${hx(t.color,'#3a3f47')};--p:${hx(t.primary,'#ffffff')};--s:${hx(t.secondary,'#d1d5db')}${t.nameOutline?`;--no:${hx(t.nameOutline,'#000')}`:''}${t.nameScale?`;--ns:${Number(t.nameScale)||1}`:''}${url(t.logo)?`;--logo:url('${url(t.logo)}')`:''}">${url(t.logo)?'<span class="sc-mark" aria-hidden="true"></span>':''}<span class="sc-logo">${logo(t)}</span><span class="sc-name"><strong data-n="${esc(t.name)}">${esc(t.name)}</strong></span><span class="sc-numbers"><span class="sc-record">${s.w}-${s.l}</span><small class="sc-lbl">W&ndash;L</small></span></article>`;
  const row=(n,inner,t)=>`<div class="seed-row"><span class="seed-num" aria-label="Seed ${n}">${n}</span>${inner}${t?teamDrawer(t):''}</div>`;
  const ghost=()=>`<article class="seed-card ghost" aria-label="Team to be announced"><span class="sc-logo"><img src="/assets/rnba-logo.png" alt="" width="64" height="64" loading="lazy"></span><span class="sc-name"></span><span class="sc-numbers"></span></article>`;
  const tier=(title,note,cls,cards)=>`<div class="tier ${cls}"><div class="tier-head"><h3>${title}</h3><small>${note}</small></div><div class="tier-cards">${cards}</div></div>`;
  const list=order(lg.teams);const real=list.length>0;
  const slice=(a,b)=>real?list.slice(a,b).map((x,i)=>row(a+i+1,card(x),x.t)).join(''):Array.from({length:b-a},(_,i)=>row(a+i+1,ghost())).join('');
  const p=playoffSpots,q=playoffSpots+playInSpots,n=Math.max(teamsPerConference,q+1);
  return `<section class="standings-board" data-standings><div class="conf-switch" role="group" aria-label="Admin" data-admin-only hidden><a class="conf-btn all" href="${lg.standings}" aria-pressed="true">Standings</a><a class="conf-btn edit" href="${lg.admin}">${icon('lock')} Edit Standings</a></div><section class="conf-view conf-super"><header class="conf-title"><img class="conf-logo" src="/assets/rnba-logo.png?v=${BUILD}" alt="RNBA" width="1254" height="1254"><span class="sr-only">RNBA SUPER CONFERENCE</span></header><div class="tiers">${tier('PLAYOFFS',`Seeds 1–${p}`,'tier-playoffs',slice(0,p))}<div class="tier-stack">${tier('PLAY-IN',`Seeds ${p+1}–${q}`,'tier-playin',slice(p,q))}${tier('OUT OF PLAYOFFS',`Seed${n-q>1?'s':''} ${q+1}${n-q>1?'–'+n:''}`,'tier-lottery',real?slice(q,Infinity)||'<p class="tier-empty">No teams</p>':slice(q,n))}</div></div></section></section>`;
}
function gameTime(game){if(!game.tipoff||!Number.isFinite(Date.parse(game.tipoff)))return '<p class="game-time">Tipoff to be announced</p>';return `<time class="game-time" datetime="${esc(game.tipoff)}" data-time="${esc(game.tipoff)}">${esc(new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(game.tipoff)))}</time>`;}
function schedulePage(){
  const weeks=[...new Set(games.map(g=>g.week).filter(w=>w!=null))].sort((a,b)=>a-b);
  return `<section data-filter-region><div class="filter-toolbar page-toolbar">${chips([{label:'All games',value:'all'},{label:'Upcoming',value:'scheduled'},{label:'Results',value:'final'},{label:'Postponed',value:'postponed'}],'games')}<div class="select-controls"><label class="select-label">Week<select data-week aria-label="Filter schedule by week"><option value="all">All weeks</option>${weeks.map(w=>`<option value="${esc(w)}">Week ${esc(w)}</option>`).join('')}</select></label><label class="select-label">Times<select data-timezone aria-label="Time zone"><option value="America/New_York">Eastern Time</option><option value="local">My local time</option></select></label></div></div><div class="game-list">${[...games].sort((a,b)=>(Date.parse(a.tipoff)||Infinity)-(Date.parse(b.tipoff)||Infinity)).map(g=>`<article class="game-card" data-filter-item data-category="${esc(g.status)}" data-week="${esc(g.week)}"><div class="game-meta"><span class="tag">${esc(({scheduled:'Upcoming',final:'Final',postponed:'Postponed'})[g.status]||g.status)}</span><span>${g.week!=null?'WEEK '+esc(g.week):'RNBA'}</span></div><div class="matchup"><div>${teamName(g.awayId)}${g.status==='final'?`<b>${esc(g.awayScore)}</b>`:''}</div><span class="versus">VS</span><div>${teamName(g.homeId)}${g.status==='final'?`<b>${esc(g.homeScore)}</b>`:''}</div></div><div class="game-bottom">${gameTime(g)}${url(g.replayUrl)?link('Watch replay',url(g.replayUrl),'text-link','external'):''}</div></article>`).join('')}</div>${!games.length?`<div class="data-panel">${empty('calendar','THE NEXT TIPOFF IS ON ITS WAY.','Matchups, dates, and final scores will live here. Check back for the official RNBA schedule.',link('Explore league media','/media/','button outline'))}</div>`:''}${noResults}</section>`;
}
